PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?rebalance_count
WHERE {
  {
    SELECT ?investorId (COUNT(?scenarioRebalanceId) AS ?rebalance_count)
    WHERE {
      ?reb a wm:ScenarioRebalancing ;
           wm:triggeredAction ?action ;
           wm:scenarioRebalanceId ?scenarioRebalanceId ;
           wm:scenarioRebalancingOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
      FILTER(LCASE(STR(?action)) = "automated trigger")
    }
    GROUP BY ?investorId
  }
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
