SELECT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  FILTER NOT EXISTS { ?investor wm:hasCategory ?cat . }

  FILTER NOT EXISTS {
    ?cf a wm:CashFlow ;
        wm:cashFlowOfInvestor ?investor .
  }

  FILTER NOT EXISTS {
    ?hold a wm:PortfolioHolding ;
          wm:heldByInvestor ?investor .
  }

  FILTER NOT EXISTS {
    ?ph a wm:PortfolioHealth ;
        wm:healthOfInvestor ?investor .
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasSectorAllocation ?sectorAlloc ;
            wm:hasRebalancingAction ?rebAction .

  ?sectorAlloc wm:allocationPct ?allocPct .
  FILTER (xsd:decimal(?allocPct) > 20)

  ?rebAction wm:action ?action .
  FILTER (LCASE(?action) = "sell")

  {
    SELECT ?investor (SUM(xsd:decimal(?withdrawAmt)) AS ?withdrawal_sum) (SUM(xsd:decimal(?depositAmt)) AS ?deposit_sum)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:type ?type .
      BIND( IF(LCASE(?type) = "withdrawal", xsd:decimal(?amount), 0) AS ?withdrawAmt )
      BIND( IF(LCASE(?type) = "deposit",    xsd:decimal(?amount), 0) AS ?depositAmt )
    }
    GROUP BY ?investor
    HAVING (SUM(xsd:decimal(?withdrawAmt)) > SUM(xsd:decimal(?depositAmt)))
  }

  FILTER EXISTS {
    ?scenario a wm:MarketScenario ;
              rdfs:label ?scenarioLabel .
    FILTER (LCASE(?scenarioLabel) = "flash crash")
  }
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avg_progress ?total_withdrawal
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:riskTolerance ?riskTol .
  FILTER(xsd:decimal(?riskTol) > 50) .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?inv (AVG(xsd:decimal(?progressPct)) AS ?avg_progress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:progressPct ?progressPct ;
            wm:belongsToInvestor ?inv .
      FILTER(xsd:decimal(?progressPct) < 40)
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?total_withdrawal)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:type ?type ;
          wm:amount ?amount .
      FILTER(LCASE(STR(?type)) = "withdrawal")
    }
    GROUP BY ?inv
  }
}
ORDER BY DESC(?total_withdrawal) ?investorId
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?investorId ?gold_holding_count ?underfunded_goal_count
WHERE {
  # Base investor with Aggressive risk tolerance
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "aggressive")

  # Aggregate Gold holdings per investor
  {
    SELECT ?investorId (COUNT(?holdingId) AS ?gold_holding_count)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investmentName ?invName ;
               wm:investorId ?investorId ;
               wm:holdingId ?holdingId .
      FILTER(LCASE(STR(?invName)) = "gold")
    }
    GROUP BY ?investorId
    HAVING (COUNT(?holdingId) > 0)
  }

  # Aggregate underfunded goals per investor
  {
    SELECT ?investorId (COUNT(?goalId) AS ?underfunded_goal_count)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfall ;
            wm:investorId ?investorId ;
            wm:goalId ?goalId .
      FILTER(xsd:decimal(?shortfall) > 0)
    }
    GROUP BY ?investorId
    HAVING (COUNT(?goalId) > 0)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?withdrawal_sum ?deposit_sum ?liquidityScore ?negative_holding_count
WHERE {
  # Investor core data and liquidity filter
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasPortfolioHealth ?ph .
  ?ph wm:liquidityScore ?liqScoreRaw .
  BIND(xsd:decimal(?liqScoreRaw) AS ?liquidityScore)
  FILTER(?liquidityScore < 30)

  # Cash?flow aggregates per investor
  {
    SELECT ?investorId (SUM(?withdrawAmt) AS ?withdrawal_sum) (SUM(?depositAmt) AS ?deposit_sum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt ;
          wm:type ?cfType .
      ?inv wm:investorId ?investorId .
      BIND( IF(LCASE(STR(?cfType)) = "withdrawal", xsd:decimal(?amt), 0) AS ?withdrawAmt )
      BIND( IF(LCASE(STR(?cfType)) = "deposit",    xsd:decimal(?amt), 0) AS ?depositAmt )
    }
    GROUP BY ?investorId
  }

  # Count of negative?return holdings per investor
  {
    SELECT ?investorId (COUNT(?hold) AS ?negative_holding_count)
    WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:heldByInvestor ?inv ;
            wm:returnsPct ?ret .
      ?inv wm:investorId ?investorId .
      BIND(xsd:decimal(?ret) AS ?retVal)
      FILTER(?retVal < 0)
    }
    GROUP BY ?investorId
  }

  # Withdrawal must exceed Deposit
  FILTER(?withdrawal_sum > ?deposit_sum)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:category ?invCategory .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  FILTER(CONTAINS(LCASE(STR(?invCategory)), "debt") && CONTAINS(LCASE(STR(?invCategory)), "profile"))
  FILTER NOT EXISTS {
    ?inv wm:hasHolding ?hold .
    ?hold a wm:PortfolioHolding .
    ?hold wm:category ?holdCategory .
    FILTER(CONTAINS(LCASE(STR(?holdCategory)), "debt") && CONTAINS(LCASE(STR(?holdCategory)), "holding"))
  }
}
